DROP TABLE IF EXISTS `svid_data_bt`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `svid_data_bt` (
  `kind` int(11) NOT NULL DEFAULT 1 COMMENT '0:common ver(programmer use)   1: rd initinalize 2: last time, 3:current  10: take-over 11: test 12: setup 2019/12/22 lkchena\n"don''t chage the order, cause ui will use the value to alignment layout"',
  `time_order` varchar(19) NOT NULL COMMENT 'yyyy/mm/dd hh:mm:ss 2019/12/22 lkchena',
  `ver` int(11) NOT NULL DEFAULT 0 COMMENT 'change to use increasement field\n<0: -1: temp record\n1~9999\n2019/12/28 lkchena\n\nversion: format by user define\ndefault: ''000''\n2019/12/25 lkchena',
  `ver_act` int(11) NOT NULL DEFAULT 0 COMMENT 'active version: 0: not 1:current\ndefault: 0\n2019/12/25 lkchena',
  `mfg_no` varchar(24) DEFAULT NULL COMMENT 'ikind=3(real-time) will use it, rd, last time will not use it\n2019/12/27 lkchena',
  `rd_flag` int(11) NOT NULL DEFAULT 0 COMMENT '0: prod 1: test run 2: rd\nikind=3(real-time) will use it, rd, last time will not use it\n2019/12/27 lkchena\n',
  `tool_id` varchar(12) NOT NULL COMMENT 'length extend to 12 for sintering "before/after" omi -- 2020/03/18 lkchena',
  `part_id` varchar(24) NOT NULL DEFAULT '*' COMMENT 'same mold, different customer with different spec -- 2019/12/22 lkchena',
  `mold_id` varchar(16) NOT NULL,
  `recipe_id` varchar(32) NOT NULL DEFAULT '*' COMMENT 'to be mold_id \n-- 2019/12/22 lkchena',
  `ope_no` varchar(7) NOT NULL COMMENT '2020/03/17 lkchena: for option flow, extend length to 7',
  `active` int(11) NOT NULL DEFAULT 1,
  `igroup` int(11) NOT NULL DEFAULT 0 COMMENT 'need to be primarykey:  2019/12/23 lkchena\n0: plc data\n10: manual input page\nothers\n\ndefault: 0, ui group block 2019/12/22 lkchena: only zero for spc\n',
  `iord` int(11) NOT NULL DEFAULT 1 COMMENT 'the filed order of report \nigroup, iord to be key!\nchange to be key <-- maybe show at ''no'' field\nfor ui update record  -- 2019/12/26 lkchena',
  `sour1` int(11) NOT NULL DEFAULT 0 COMMENT '0: not use(blank), \n1:plc, \n2:manual number -- 2019/12/29 lkchena\n3:manual string  -- 2019/12/29 lkchena\n5: others, \n9:hint(just title or note), \n10: title line 11:spliter line, \n80: plc use 1a,1b replace sour1\n2019/12/25 lkchena',
  `nx1` varchar(12) NOT NULL DEFAULT '0' COMMENT 'default:0,not use\nn99: plc table filed, use value1 number field\n2019/12/24 lkchena\n\nremove -- 2019/12/29 lkchena\n10: use value1s string field( for igroup=10, string field data)\n',
  `field_name1` varchar(24) NOT NULL,
  `field_desc1` varchar(64) DEFAULT NULL,
  `value1` double DEFAULT NULL COMMENT 'current value -- 2019/12/22 lkchena',
  `value1s` varchar(32) DEFAULT NULL,
  `unit1` varchar(8) DEFAULT NULL,
  `csl1` double DEFAULT NULL,
  `sign1` double DEFAULT NULL,
  `lsl1` double DEFAULT NULL,
  `usl1` double DEFAULT NULL,
  `sour2` int(11) NOT NULL DEFAULT 0 COMMENT 'like sour1, but no 88',
  `nx2` varchar(12) NOT NULL DEFAULT '0' COMMENT 'like nx1 -- 2019/12/24 lkchena',
  `field_name2` varchar(24) NOT NULL,
  `field_desc2` varchar(64) DEFAULT NULL,
  `value2` double DEFAULT NULL COMMENT 'current value -- 2019/12/22 lkchena',
  `value2s` varchar(32) DEFAULT NULL,
  `unit2` varchar(8) DEFAULT NULL,
  `csl2` double DEFAULT NULL,
  `sign2` double DEFAULT NULL,
  `lsl2` double DEFAULT NULL,
  `usl2` double DEFAULT NULL,
  `sour3` int(11) NOT NULL DEFAULT 0 COMMENT 'like sour1, but no 88',
  `nx3` varchar(12) NOT NULL DEFAULT '0' COMMENT 'like nx1 -- 2019/12/24 lkchena',
  `field_name3` varchar(24) NOT NULL,
  `field_desc3` varchar(64) DEFAULT NULL,
  `value3` double DEFAULT NULL COMMENT 'current value -- 2019/12/22 lkchena',
  `value3s` varchar(32) DEFAULT NULL,
  `unit3` varchar(8) DEFAULT NULL,
  `csl3` double DEFAULT NULL,
  `sign3` double DEFAULT NULL,
  `lsl3` double DEFAULT NULL,
  `usl3` double DEFAULT NULL,
  `sour1a` int(11) NOT NULL DEFAULT 0 COMMENT 'like sour1, but no 88',
  `nx1a` varchar(12) NOT NULL DEFAULT '0' COMMENT 'like nx1 -- 2019/12/24 lkchena',
  `field_name1a` varchar(24) NOT NULL DEFAULT '*',
  `field_desc1a` varchar(64) DEFAULT NULL,
  `value1a` double DEFAULT NULL COMMENT 'current value -- 2019/12/22 lkchena',
  `value1as` varchar(32) DEFAULT NULL,
  `sour1b` int(11) NOT NULL DEFAULT 0 COMMENT 'like sour1, but no 88',
  `nx1b` varchar(12) NOT NULL DEFAULT '0' COMMENT 'like nx1 -- 2019/12/24 lkchena',
  `field_name1b` varchar(24) NOT NULL DEFAULT '*',
  `field_desc1b` varchar(64) DEFAULT NULL,
  `value1b` double DEFAULT NULL COMMENT 'current value -- 2019/12/22 lkchena',
  `value1bs` varchar(32) DEFAULT NULL,
  `freq` int(11) NOT NULL DEFAULT -1 COMMENT 'data collect frequency: unit: second, -1: ignore(or event trigger)',
  `note` varchar(256) DEFAULT 'NULL',
  `rec_user` varchar(16) DEFAULT 'NULL',
  `rec_time` varchar(19) DEFAULT NULL,
  `itag` int(11) DEFAULT 0 COMMENT 'switch temporary field for show real-time svid  2020/01/12 lkchena\nuse at ussp_subRT_0_set_tag/ussp_subRT_1_write_rt_value',
  `node_id` varchar(16) DEFAULT NULL,
  `node_time` timestamp(6) NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`kind`,`time_order`,`ver`,`ver_act`,`tool_id`,`part_id`,`mold_id`,`ope_no`,`igroup`,`iord`,`field_name1`),
  KEY `idx1` (`tool_id`,`part_id`,`mold_id`,`kind`,`recipe_id`,`ope_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

